def repartir_terminale(apps, schema_editor):
    """En Terminale chaque série a son programme : les anciennes lignes (valables pour tout le niveau) deviennent
    une ligne par classe qui enseigne la matière. La 3ème garde un programme commun."""
    from scolarite.passage import normaliser_niveau
    Programme = apps.get_model('evaluations', 'ProgrammeExamenBlanc')
    Classe = apps.get_model('scolarite', 'Classe')
    ClasseMatiere = apps.get_model('cours', 'ClasseMatiere')
    for p in Programme.objects.filter(classe__isnull=True).select_related('calendrier__niveau'):
        if normaliser_niveau(p.calendrier.niveau.nom) != 'Terminale':
            continue
        crees = 0
        for c in Classe.objects.filter(niveau_id=p.calendrier.niveau_id):
            if not ClasseMatiere.objects.filter(classe=c, matiere_id=p.matiere_id).exists():
                continue
            Programme.objects.get_or_create(
                calendrier_id=p.calendrier_id, classe=c, matiere_id=p.matiere_id,
                defaults={'contenu': p.contenu, 'date_examen': p.date_examen, 'heure_debut': p.heure_debut,
                          'heure_fin': p.heure_fin, 'ecole_id': p.ecole_id},
            )
            crees += 1
        if crees:
            p.delete()


